export const MAP_CONSTANTS = {
    MAPBOX_TOKEN: process.env.REACT_APP_MAPBOX_TOKEN,
    MAP_TXT : "map",
    PLAN_TXT: "plan",
    AERIAL_TXT: "aerialPhoto"
}

if (!MAP_CONSTANTS.MAPBOX_TOKEN) {
    console.error("REACT_APP_MAPBOX_TOKEN is not set. Copy mapui/.env.example to mapui/.env.local " +
        "and put your Mapbox public token (pk...) in it, then restart or rebuild.");
}
