//https://ilayaydin.wordpress.com/2018/10/29/aa/
// The layer list lives in src/layers.json, so a map can be added or moved to another
// Mapbox tileset without touching code. tools/mapbox_upload.py writes "source" there
// after an upload. "type" is one of the MAP_CONSTANTS values (map, plan, aerialPhoto).
import catalog from "../../layers.json";

export const layers = catalog.layers.map(({ id, source, minzoom, maxzoom, displayName, type }) =>
    ({ id, source, minzoom, maxzoom, displayName, type }));
